"""Load corpus/research-import/ (generated by import-research) for DEV builds (ADR 0008)."""

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import yaml

from .errors import PipelineError
from .research_import import ORIGIN


@dataclass
class ResearchSet:
    nodes: list[dict[str, Any]] = field(default_factory=list)
    counter_questions: list[dict[str, Any]] = field(default_factory=list)
    edges: list[dict[str, str]] = field(default_factory=list)


def load_research(folder: Path, topic_ids: set[str], opponent_ids: set[str]) -> ResearchSet | None:
    if not (folder / "nodes.yaml").is_file():
        return None
    load = lambda name: yaml.safe_load((folder / name).read_text(encoding="utf-8")) or []  # noqa: E731
    rs = ResearchSet(load("nodes.yaml"), load("counter_questions.yaml"), load("edges.yaml"))
    problems: list[str] = []
    ids: set[str] = set()
    for n in rs.nodes + rs.counter_questions:
        if n.get("origin") != ORIGIN or n.get("status") != "draft":
            problems.append(f"{n.get('id')}: must be origin {ORIGIN} and status draft")
        if n["id"] in ids:
            problems.append(f"duplicate id {n['id']}")
        ids.add(n["id"])
    for n in rs.nodes:
        if n.get("topic") not in topic_ids:
            problems.append(f"{n['id']}: unknown topic {n.get('topic')}")
        for o in n.get("opponent") or []:
            if o not in opponent_ids:
                problems.append(f"{n['id']}: unknown opponent {o}")
    claim_ids = {n["id"] for n in rs.nodes}
    for e in rs.edges:
        if e["from"] not in ids or e["to"] not in claim_ids or e["kind"] not in ("follow_up", "counters"):
            problems.append(f"bad edge {e}")
    if problems:
        raise PipelineError(
            "corpus/research-import is inconsistent (re-run import-research):\n  " + "\n  ".join(problems)
        )
    return rs
